import unittest
import copy, json, sys
sys.path.insert(0, '.')

import importlib
MOD = "holdshelf.holds"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    outbox = []
    desk = mod.HoldDesk(today=lambda: int(clock.now), mail=lambda member, text: outbox.append([member, text]))
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": outbox}

def _norm(x):
    return json.loads(json.dumps(x))

def _outcome(case):
    try:
        return _norm(run_case(copy.deepcopy(case)))
    except Exception as e:
        return {"raises": type(e).__name__}

