import json
import unittest

import importlib
MOD = "holdshelf.holds"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    outbox = []
    desk = mod.HoldDesk(today=lambda: int(clock.now), mail=lambda member, text: outbox.append([member, text]))
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": outbox}

def norm(x):
    return json.loads(json.dumps(x))


class HoldDeskTests(unittest.TestCase):
    def test_scenario_1(self):
        case = json.loads("{\"t0\": 739000, \"ops\": [[\"place_hold\", \"max\", \"Kiln Manual\"], [\"place_hold\", \"kit\", \"Kiln Manual\"], [\"place_hold\", \"lou\", \"Kiln Manual\"], [\"place_hold\", \"max\", \"Dune Atlas\"], [\"place_hold\", \"ila\", \"Moss Field Guide\"], [\"advance\", 2], [\"return_book\", \"Moss Field Guide\"], [\"place_hold\", \"kit\", \"Moss Field Guide\"], [\"place_hold\", \"joss\", \"Dune Atlas\"], [\"place_hold\", \"kit\", \"Tide Almanac\"], [\"place_hold\", \"kit\", \"Kiln Manual\"], [\"return_book\", \"Dune Atlas\"], [\"return_book\", \"Kiln Manual\"], [\"return_book\", \"Kiln Manual\"], [\"place_hold\", \"lou\", \"Kiln Manual\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 2, 3, 1, 1, \"ila\", 1, 2, {\"raises\": \"ValueError\"}, {\"raises\": \"ValueError\"}, \"max\", \"max\", \"kit\", {\"raises\": \"ValueError\"}, [\"joss\"], []], \"notes\": [[\"ila\", \"Moss Field Guide is ready for you for 5 days\"], [\"max\", \"Dune Atlas is ready for you for 5 days\"], [\"max\", \"Kiln Manual is ready for you for 5 days\"], [\"kit\", \"Kiln Manual is ready for you for 5 days\"]]}"))

    def test_scenario_2(self):
        case = json.loads("{\"t0\": 739000, \"ops\": [[\"place_hold\", \"ila\", \"Dune Atlas\"], [\"place_hold\", \"kit\", \"Dune Atlas\"], [\"advance\", 4], [\"place_hold\", \"lou\", \"Kiln Manual\"], [\"waiting\", \"Dune Atlas\"], [\"return_book\", \"Moss Field Guide\"], [\"advance\", 4], [\"return_book\", \"Kiln Manual\"], [\"return_book\", \"Tide Almanac\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 2, 1, [\"ila\", \"kit\"], null, \"lou\", null, [\"ila\", \"kit\"], []], \"notes\": [[\"lou\", \"Kiln Manual is ready for you for 5 days\"]]}"))

    def test_scenario_3(self):
        case = json.loads("{\"t0\": 739000, \"ops\": [[\"return_book\", \"Dune Atlas\"], [\"advance\", 4], [\"advance\", 2], [\"place_hold\", \"joss\", \"Dune Atlas\"], [\"return_book\", \"Tide Almanac\"], [\"place_hold\", \"max\", \"Dune Atlas\"], [\"place_hold\", \"kit\", \"Moss Field Guide\"], [\"return_book\", \"Moss Field Guide\"], [\"advance\", 1], [\"waiting\", \"Tide Almanac\"], [\"advance\", 6], [\"advance\", 1], [\"place_hold\", \"kit\", \"Dune Atlas\"], [\"advance\", 15], [\"place_hold\", \"kit\", \"Dune Atlas\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [null, 1, null, 2, 1, \"kit\", [], 3, {\"raises\": \"ValueError\"}, [\"joss\", \"max\", \"kit\"], []], \"notes\": [[\"kit\", \"Moss Field Guide is ready for you for 5 days\"]]}"))


if __name__ == '__main__':
    unittest.main()

