import json
import unittest

import importlib
MOD = "plantwatch.alerts"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    outbox = []
    desk = mod.AlertDesk(limits={"temp": 5.5, "vibration": 30.0, "pressure": 5.5}, clock=clock, send=lambda to, text: outbox.append([to, text]))
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": outbox}

def norm(x):
    return json.loads(json.dumps(x))


class AlertDeskTests(unittest.TestCase):
    def test_scenario_1(self):
        case = json.loads("{\"t0\": 100, \"ops\": [[\"record\", \"temp\", 7.5], [\"record\", \"pressure\", 14.5], [\"advance\", 10], [\"record\", \"vibration\", 39.0], [\"record\", \"temp\", 14.5], [\"record\", \"temp\", 2.5], [\"advance\", 300], [\"record\", \"vibration\", 29.5], [\"record\", \"vibration\", 30.0], [\"advance\", 299]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [true, true, true, false, false, false, false], \"notes\": [[\"ops@plant.example\", \"temp high: 7.5\"], [\"ops@plant.example\", \"pressure high: 14.5\"], [\"ops@plant.example\", \"vibration high: 39.0\"]]}"))

    def test_scenario_2(self):
        case = json.loads("{\"t0\": 100, \"ops\": [[\"record\", \"temp\", 6.0], [\"record\", \"vibration\", 32.0], [\"record\", \"temp\", 14.5], [\"advance\", 600], [\"record\", \"vibration\", 30.0], [\"record\", \"vibration\", 27.0], [\"quiet_since\", \"temp\"], [\"record\", \"pressure\", 14.5], [\"record\", \"vibration\", 27.0], [\"record\", \"vibration\", 39.0], [\"record\", \"vibration\", 30.5]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [true, true, false, false, false, 100, true, false, false, false], \"notes\": [[\"ops@plant.example\", \"temp high: 6.0\"], [\"ops@plant.example\", \"vibration high: 32.0\"], [\"ops@plant.example\", \"pressure high: 14.5\"]]}"))

    def test_scenario_3(self):
        case = json.loads("{\"t0\": 100, \"ops\": [[\"record\", \"vibration\", 27.0], [\"quiet_since\", \"vibration\"], [\"record\", \"vibration\", 30.5], [\"advance\", 1799], [\"advance\", 200], [\"record\", \"vibration\", 32.0], [\"record\", \"temp\", 7.5], [\"record\", \"temp\", 7.5], [\"record\", \"vibration\", 32.0]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [false, null, true, true, true, false, false], \"notes\": [[\"ops@plant.example\", \"vibration high: 30.5\"], [\"ops@plant.example\", \"vibration high: 32.0\"], [\"ops@plant.example\", \"temp high: 7.5\"]]}"))


if __name__ == '__main__':
    unittest.main()

