        case = json.loads("{\"t0\": 739000, \"ops\": [[\"place_hold\", \"max\", \"Kiln Manual\"], [\"advance\", 4], [\"place_hold\", \"ila\", \"Tide Almanac\"], [\"place_hold\", \"joss\", \"Dune Atlas\"], [\"return_book\", \"Tide Almanac\"], [\"place_hold\", \"ila\", \"Dune Atlas\"], [\"place_hold\", \"ila\", \"Moss Field Guide\"], [\"return_book\", \"Tide Almanac\"], [\"place_hold\", \"kit\", \"Dune Atlas\"], [\"advance\", 2], [\"return_book\", \"Moss Field Guide\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
