        case = json.loads("{\"t0\": 739000, \"ops\": [[\"advance\", 2], [\"return_book\", \"Tide Almanac\"], [\"advance\", 4], [\"place_hold\", \"ila\", \"Tide Almanac\"], [\"return_book\", \"Dune Atlas\"], [\"advance\", 2], [\"return_book\", \"Moss Field Guide\"], [\"return_book\", \"Kiln Manual\"], [\"place_hold\", \"ila\", \"Tide Almanac\"], [\"place_hold\", \"lou\", \"Moss Field Guide\"], [\"place_hold\", \"kit\", \"Dune Atlas\"], [\"advance\", 2], [\"place_hold\", \"ila\", \"Tide Almanac\"], [\"return_book\", \"Moss Field Guide\"], [\"place_hold\", \"lou\", \"Moss Field Guide\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
