import json
import unittest

import importlib, random
MOD = "promo.coupons"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    notes = []
    desk = mod.CouponDesk(percent={"loyal": 5, "referral": 20, "welcome": 5}, rng=random.Random(case["seed"]), clock=clock, notify=notes.append)
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": notes}

def norm(x):
    return json.loads(json.dumps(x))


class CouponDeskTests(unittest.TestCase):
    def test_scenario_1(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 696598, \"ops\": [[\"issue\", \"cora\", \"loyal\"], [\"advance\", 3000], [\"redeem\", {\"ref\": 0}, \"ben\", 1999], [\"issue\", \"cora\", \"welcome\"], [\"redeem\", {\"ref\": 0}, \"cora\", 12000], [\"advance\", 3000], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"TPYSD\", {\"raises\": \"PermissionError\"}, \"WV5JJ\", 600, [], []], \"notes\": [\"redeemed TPYSD for cora: -600\"]}"))

    def test_scenario_2(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 389577, \"ops\": [[\"issue\", \"ben\", \"loyal\"], [\"redeem\", {\"ref\": 0}, \"cora\", 12000], [\"redeem\", {\"ref\": 0}, \"ana\", 1999], [\"redeem\", {\"ref\": 0}, \"ben\", 500], [\"redeem\", {\"ref\": 0}, \"ana\", 500], [\"advance\", 3000], [\"issue\", \"ben\", \"referral\"], [\"issue\", \"ben\", \"referral\"], [\"redeem\", {\"ref\": 6}, \"ben\", 1999], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"RAMM7\", {\"raises\": \"PermissionError\"}, {\"raises\": \"PermissionError\"}, 25, {\"raises\": \"PermissionError\"}, \"PZ6KL\", \"FHG4E\", 399, [], [\"PZ6KL\"]], \"notes\": [\"redeemed RAMM7 for ben: -25\", \"redeemed FHG4E for ben: -399\"]}"))

    def test_scenario_3(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 951105, \"ops\": [[\"issue\", \"ben\", \"referral\"], [\"redeem\", {\"ref\": 0}, \"ben\", 12000], [\"issue\", \"ben\", \"loyal\"], [\"redeem\", {\"ref\": 2}, \"ben\", 12000], [\"issue\", \"ben\", \"loyal\"], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"D82WJ\", 2400, \"QNTRV\", 600, \"ELHRZ\", [], [\"ELHRZ\"]], \"notes\": [\"redeemed D82WJ for ben: -2400\", \"redeemed QNTRV for ben: -600\"]}"))


