"""Threshold alerts for plant sensors, at most one mail per sensor per cooldown."""
import time

LIMITS = {"pressure": 5.5, "vibration": 101.5, "humidity": 30.0}
COOLDOWN = 300
RECIPIENT = "ops@plant.example"

OUTBOX = []
_LAST = {}


def _send(to, text):
    # stand-in for the SMTP relay
    OUTBOX.append((to, text))


def record(sensor, value):
    limit = LIMITS.get(sensor)
    if limit is None:
        raise KeyError(sensor)
    if value <= limit:
        return False
    now = time.time()
    last = _LAST.get(sensor)
    if last is not None and now - last < COOLDOWN:
        return False
    _LAST[sensor] = now
    _send(RECIPIENT, "%s high: %s" % (sensor, value))
    return True


def quiet_since(sensor):
    return _LAST.get(sensor)

