import json
import unittest

import importlib, random
MOD = "promo.coupons"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    notes = []
    desk = mod.CouponDesk(percent={"loyal": 15, "referral": 25, "birthday": 10}, rng=random.Random(case["seed"]), clock=clock, notify=notes.append)
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": notes}

def norm(x):
    return json.loads(json.dumps(x))


class CouponDeskTests(unittest.TestCase):
    def test_scenario_1(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 838950, \"ops\": [[\"issue\", \"ben\", \"referral\"], [\"redeem\", {\"ref\": 0}, \"ben\", 12000], [\"issue\", \"ana\", \"referral\"], [\"redeem\", {\"ref\": 0}, \"ana\", 12000], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"P2FP97\", 3000, \"P3W654\", {\"raises\": \"PermissionError\"}, [\"P3W654\"], []], \"notes\": [\"redeemed P2FP97 for ben: -3000\"]}"))

