        case = json.loads("{\"t0\": 5000, \"seed\": 734583, \"ops\": [[\"issue\", \"ana\", \"birthday\"], [\"outstanding\", \"ben\"], [\"issue\", \"ana\", \"birthday\"], [\"redeem\", {\"ref\": 0}, \"ana\", 12000], [\"redeem\", {\"ref\": 2}, \"cora\", 12000], [\"redeem\", {\"ref\": 2}, \"ana\", 1999], [\"advance\", 60], [\"redeem\", {\"ref\": 0}, \"cora\", 1999], [\"redeem\", {\"ref\": 2}, \"ben\", 1999], [\"advance\", 90000], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"JDSALA\", [], \"DA6J3H\", 1200, {\"raises\": \"PermissionError\"}, 199, {\"raises\": \"PermissionError\"}, {\"raises\": \"PermissionError\"}, [], []], \"notes\": [\"redeemed JDSALA for ana: -1200\", \"redeemed DA6J3H for ana: -199\"]}"))

    def test_scenario_3(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 713501, \"ops\": [[\"issue\", \"ben\", \"birthday\"], [\"outstanding\", \"cora\"], [\"issue\", \"ana\", \"birthday\"], [\"issue\", \"ana\", \"loyal\"], [\"redeem\", {\"ref\": 3}, \"ana\", 1999], [\"redeem\", {\"ref\": 3}, \"cora\", 500], [\"redeem\", {\"ref\": 0}, \"cora\", 1999], [\"issue\", \"cora\", \"referral\"], [\"redeem\", {\"ref\": 0}, \"cora\", 500], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
