import json
import unittest

import importlib, random
MOD = "promo.coupons"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    notes = []
    desk = mod.CouponDesk(percent={"welcome": 20, "apology": 10, "referral": 15}, rng=random.Random(case["seed"]), clock=clock, notify=notes.append)
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": notes}

def norm(x):
    return json.loads(json.dumps(x))


class CouponDeskTests(unittest.TestCase):
    def test_scenario_1(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 948242, \"ops\": [[\"issue\", \"ana\", \"welcome\"], [\"outstanding\", \"ben\"], [\"outstanding\", \"cora\"], [\"redeem\", {\"ref\": 0}, \"ben\", 1999], [\"issue\", \"cora\", \"referral\"], [\"issue\", \"ana\", \"welcome\"], [\"advance\", 3000], [\"issue\", \"ana\", \"welcome\"], [\"redeem\", {\"ref\": 4}, \"cora\", 500], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"JWWWQ\", [], [], {\"raises\": \"PermissionError\"}, \"YWW8T\", \"539XE\", \"RRWTY\", 75, [\"539XE\", \"JWWWQ\", \"RRWTY\"], []], \"notes\": [\"redeemed YWW8T for cora: -75\"]}"))

    def test_scenario_2(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 151106, \"ops\": [[\"issue\", \"cora\", \"welcome\"], [\"issue\", \"cora\", \"referral\"], [\"advance\", 3000], [\"redeem\", {\"ref\": 1}, \"cora\", 12000], [\"issue\", \"ana\", \"referral\"], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"3M3N9\", \"7SKAF\", 1800, \"LR3KE\", [\"LR3KE\"], []], \"notes\": [\"redeemed 7SKAF for cora: -1800\"]}"))

    def test_scenario_3(self):
        case = json.loads("{\"t0\": 5000, \"seed\": 824601, \"ops\": [[\"issue\", \"ana\", \"apology\"], [\"issue\", \"ana\", \"referral\"], [\"redeem\", {\"ref\": 1}, \"ana\", 500], [\"issue\", \"ben\", \"welcome\"], [\"issue\", \"cora\", \"apology\"], [\"redeem\", {\"ref\": 1}, \"ana\", 1999], [\"outstanding\", \"ana\"], [\"redeem\", {\"ref\": 0}, \"ben\", 1999], [\"outstanding\", \"ana\"], [\"outstanding\", \"ben\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [\"SJRNJ\", \"WRF8Y\", 75, \"EBMXS\", \"3XY3Y\", {\"raises\": \"ValueError\"}, [\"SJRNJ\"], {\"raises\": \"PermissionError\"}, [\"SJRNJ\"], [\"EBMXS\"]], \"notes\": [\"redeemed WRF8Y for ana: -75\"]}"))


