import json
import unittest

import importlib
MOD = "holdshelf.holds"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    outbox = []
    desk = mod.HoldDesk(today=lambda: int(clock.now), mail=lambda member, text: outbox.append([member, text]))
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": outbox}

def norm(x):
    return json.loads(json.dumps(x))


class HoldDeskTests(unittest.TestCase):
    def test_scenario_1(self):
        case = json.loads("{\"t0\": 739000, \"ops\": [[\"advance\", 6], [\"waiting\", \"Dune Atlas\"], [\"advance\", 4], [\"place_hold\", \"lou\", \"Kiln Manual\"], [\"place_hold\", \"max\", \"Kiln Manual\"], [\"place_hold\", \"max\", \"Tide Almanac\"], [\"place_hold\", \"ila\", \"Kiln Manual\"], [\"return_book\", \"Dune Atlas\"], [\"place_hold\", \"ila\", \"Dune Atlas\"], [\"return_book\", \"Dune Atlas\"], [\"place_hold\", \"max\", \"Tide Almanac\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [[], 1, 2, 1, 3, null, 1, \"ila\", {\"raises\": \"ValueError\"}, [], [\"max\"]], \"notes\": [[\"ila\", \"Dune Atlas is ready for you for 7 days\"]]}"))

    def test_scenario_2(self):
        case = json.loads("{\"t0\": 739000, \"ops\": [[\"place_hold\", \"lou\", \"Tide Almanac\"], [\"advance\", 6], [\"advance\", 1], [\"place_hold\", \"ila\", \"Dune Atlas\"], [\"advance\", 9], [\"waiting\", \"Dune Atlas\"], [\"advance\", 1], [\"place_hold\", \"joss\", \"Tide Almanac\"], [\"return_book\", \"Kiln Manual\"], [\"place_hold\", \"ila\", \"Moss Field Guide\"], [\"return_book\", \"Tide Almanac\"], [\"place_hold\", \"kit\", \"Moss Field Guide\"], [\"place_hold\", \"kit\", \"Kiln Manual\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 1, [\"ila\"], 2, null, 1, \"joss\", 2, 1, [\"ila\"], []], \"notes\": [[\"lou\", \"your hold on Tide Almanac expired\"], [\"joss\", \"Tide Almanac is ready for you for 7 days\"]]}"))

    def test_scenario_3(self):
        case = json.loads("{\"t0\": 739000, \"ops\": [[\"place_hold\", \"kit\", \"Tide Almanac\"], [\"place_hold\", \"max\", \"Moss Field Guide\"], [\"advance\", 15], [\"place_hold\", \"joss\", \"Moss Field Guide\"], [\"place_hold\", \"joss\", \"Dune Atlas\"], [\"place_hold\", \"joss\", \"Dune Atlas\"], [\"place_hold\", \"ila\", \"Kiln Manual\"], [\"return_book\", \"Moss Field Guide\"], [\"place_hold\", \"lou\", \"Dune Atlas\"], [\"return_book\", \"Moss Field Guide\"], [\"place_hold\", \"ila\", \"Moss Field Guide\"], [\"waiting\", \"Kiln Manual\"], [\"place_hold\", \"kit\", \"Moss Field Guide\"], [\"place_hold\", \"ila\", \"Dune Atlas\"], [\"waiting\", \"Dune Atlas\"], [\"waiting\", \"Tide Almanac\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 1, 2, 1, {\"raises\": \"ValueError\"}, 1, \"joss\", 2, null, 1, [\"ila\"], 2, 3, [\"joss\", \"lou\", \"ila\"], [\"kit\"]], \"notes\": [[\"max\", \"your hold on Moss Field Guide expired\"], [\"joss\", \"Moss Field Guide is ready for you for 7 days\"]]}"))


if __name__ == '__main__':
    unittest.main()
